#!/usr/bin/env python3
"""One-shot migration: structure-from-body → structure-in-rows + Jinja2 templates.

What this script does (run once):

  1. Add columns to `entries` for group/layout metadata:
       group_position, group_label_display, group_layout, group_separator,
       bullet_position, bullet_sub_label
  2. Walk every layer / subbranch `sections.body`, re-parse it line-by-line and
     fill those new columns on the matching entries row. The match key is
     (section_key, ref_num, url, name) — stable across migrations.
  3. Extract the prose-only prefix of each layer/subbranch body (everything
     before the first vendor/category block header or entry-bearing bullet)
     and store it as `entries`-table-adjacent prose into a new
     `prose_blocks(key, body)` table (key = section_key).
  4. For prose-only section types (doc_top, main_overview, branch_intro,
     branch, crosscut, other), copy the full body to `prose_blocks` too.
  5. Dump `prose_blocks` into Jinja2 partial files under
     chat/AISW-stack/templates/ as a starting point. Hand-editing later is OK.

After this runs, the new Jinja2-based render() (in aiswstack_controller.py)
should reproduce the README from:
  - layers + branches (taxonomy)
  - entries with group metadata (structured entries)
  - cells (summary-table)
  - refs (citations)
  - templates/*.j2 (all prose + structure)
"""

from __future__ import annotations

import re
import sqlite3
import sys
import textwrap
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DB_PATH = ROOT / "chat/AISW-stack/index.sqlite3"
TEMPLATES_DIR = ROOT / "chat/AISW-stack/templates"

# ---------------------------------------------------------------------------
# regex (mirror those in the existing controller)

REF_LINK_RE = re.compile(r"\[\[(\d+)\]\]\((https?://[^\s)]+)\)")
VENDOR_BLOCK_RE = re.compile(r"^\*\*([^*]+)\*\*[:：]\s*$")
VENDOR_INLINE_RE = re.compile(r"^\*\*([^*]+)\*\*[:：]\s*(\S.*)$")
SEP_CHARS = "、，,；;|。：:"
NAME_SPLIT_RE = re.compile(r"[" + re.escape(SEP_CHARS) + r"]|(?<=[）)\s])\+\s")
GROUP_LABEL_RE = re.compile(r"^([-*])\s+\*\*([^*]+)\*\*[:：]\s*(.*)$")
BARE_VENDOR_RE = re.compile(r"^[-*]\s+([^*：:\[]{1,24}?)[：:]\s*(.+)$")
_PUNCT_RE = re.compile(r"[\s/（）()，,、；;:：&+]+")
_SLUG_DECO_RE = re.compile(r"[*_`\"'·]")

KNOWN_VENDORS = {
    "NVIDIA", "AMD", "Intel", "Apple", "AWS", "Google", "Microsoft", "Meta",
    "Anthropic", "OpenAI", "xAI", "DeepSeek", "Mistral", "Cohere",
    "Databricks", "Snowflake", "Cloudflare", "HuggingFace", "Hugging Face",
    "IBM", "Oracle", "SAP", "Salesforce", "ServiceNow", "Workday",
    "华为", "华为昇腾", "阿里", "百度", "腾讯", "字节",
    "高通", "Qualcomm", "联发科", "MediaTek", "瑞芯微", "Rockchip",
}
VENDOR_ALIASES = {
    "华为昇腾": "华为", "华为昇腾（Ascend）": "华为",
    "Hugging Face": "HuggingFace", "Qualcomm": "高通",
    "MediaTek": "联发科", "Rockchip": "瑞芯微",
}


def canonical_vendor(label: str | None) -> str | None:
    if not label:
        return None
    plain = label.strip()
    bare = re.sub(r"（[^）]*）|\([^)]*\)", "", plain).strip()
    for cand in (plain, bare):
        if cand in VENDOR_ALIASES:
            return VENDOR_ALIASES[cand]
        if cand in KNOWN_VENDORS:
            return cand
    return None


# ---------------------------------------------------------------------------
# schema migration

ADD_COLS = [
    ("group_position", "INTEGER"),
    ("group_label_display", "TEXT"),
    ("group_layout", "TEXT"),
    ("group_separator", "TEXT"),
    ("bullet_position", "INTEGER"),
    ("bullet_sub_label", "TEXT"),
]


def ensure_columns(conn: sqlite3.Connection):
    cols = {r[1] for r in conn.execute("PRAGMA table_info(entries)").fetchall()}
    for name, ty in ADD_COLS:
        if name not in cols:
            conn.execute(f"ALTER TABLE entries ADD COLUMN {name} {ty}")
            print(f"  added entries.{name} {ty}")
    conn.execute("""
        CREATE TABLE IF NOT EXISTS prose_blocks (
            section_key  TEXT PRIMARY KEY,
            kind         TEXT NOT NULL,  -- 'intro' | 'full' | 'summary_intro'
            body         TEXT NOT NULL
        )
    """)


# ---------------------------------------------------------------------------
# parse body into prose-prefix + structured groups

def parse_section(body: str) -> tuple[str, list[dict]]:
    """Return (intro_prose, groups). `groups` is a list of dicts:
       {label_display, layout, separator, entries: [(name, ref, url, notes, sub_label, bullet_pos)]}
       `intro_prose` is everything before the first group/entry-bearing line.
    """
    lines = body.split("\n")
    # find first "entry-bearing" line
    intro_end = 0
    for i, ln in enumerate(lines):
        if VENDOR_BLOCK_RE.match(ln.strip()):
            intro_end = i; break
        if VENDOR_INLINE_RE.match(ln.strip()):
            intro_end = i; break
        if REF_LINK_RE.search(ln):
            intro_end = i; break
        if ln.strip().startswith(("-", "*")) and ln.strip().lstrip("-*").strip():
            intro_end = i; break
    else:
        intro_end = len(lines)
    intro = "\n".join(lines[:intro_end]).rstrip()
    rest = lines[intro_end:]

    groups: list[dict] = []
    # state
    cur_group: dict | None = None
    bullet_pos = 0

    def start_group(label_display, layout, separator):
        nonlocal cur_group, bullet_pos
        cur_group = {
            "label_display": label_display, "layout": layout,
            "separator": separator, "entries": []
        }
        groups.append(cur_group)
        bullet_pos = 0

    def ensure_default_group():
        nonlocal cur_group
        if cur_group is None:
            start_group(None, "bullets", None)

    for raw_line in rest:
        line = raw_line.rstrip()
        stripped = line.strip()
        if not stripped:
            continue
        # vendor/category block header on its own line → start bullets group
        m = VENDOR_BLOCK_RE.match(stripped)
        if m:
            start_group(m.group(1).strip(), "bullets", None)
            continue
        # vendor/category inline (label + content on same line) → start inline group
        m = VENDOR_INLINE_RE.match(stripped)
        if m:
            label = m.group(1).strip()
            content = m.group(2).strip()
            sep = _infer_inline_separator(content)
            start_group(label, "inline", sep)
            for ent in extract_inline_entries(content):
                cur_group["entries"].append(
                    {**ent, "sub_label": None, "bullet_position": None}
                )
            continue
        if stripped.startswith(("-", "*")):
            # bullet line — either standalone bullet under current group or
            # standalone bullet not under any group (start a default)
            ensure_default_group()
            inner = re.sub(r"^[-*]\s+", "", stripped)
            sub_label = None
            # detect sub-vendor prefix `**X**：` at start of bullet
            m_lbl = GROUP_LABEL_RE.match(stripped)
            if m_lbl:
                sub_label = m_lbl.group(2).strip()
                inner = m_lbl.group(3).strip()
                if cur_group.get("layout") != "bullets":
                    # promote group to bullets if it was inline (rare)
                    cur_group["layout"] = "bullets"
            else:
                m_bv = BARE_VENDOR_RE.match(stripped)
                if m_bv:
                    sub_label = m_bv.group(1).strip()
                    inner = m_bv.group(2).strip()
            ents = extract_inline_entries(inner) if (
                "+" in inner or "、" in inner or "," in inner
            ) else extract_single_entry_or_inline(inner)
            for ent in ents:
                cur_group["entries"].append(
                    {**ent, "sub_label": sub_label, "bullet_position": bullet_pos}
                )
            bullet_pos += 1
            continue
        if REF_LINK_RE.search(line):
            # bare prose line with refs (rare in layer/sub but seen in crosscut etc.)
            ensure_default_group()
            for ent in extract_inline_entries(line):
                cur_group["entries"].append(
                    {**ent, "sub_label": None, "bullet_position": None}
                )

    return intro, groups


def _infer_inline_separator(content: str) -> str:
    if "、" in content:
        return "、"
    if " + " in content:
        return " + "
    if ", " in content:
        return ", "
    return "、"


def extract_inline_entries(text: str):
    """Walk text for `Name[[N]](url)（notes）?` tokens left-to-right."""
    out = []
    for m in REF_LINK_RE.finditer(text):
        ref_num = int(m.group(1))
        url = m.group(2)
        before = text[:m.start()]
        parts = NAME_SPLIT_RE.split(before)
        raw_name = parts[-1] if parts else ""
        name = _clean_name(raw_name)
        if not _valid_name(name):
            continue
        notes = _trailing_notes(text, m.end())
        out.append({"name": name, "ref_num": ref_num, "url": url, "notes": notes})
    return out


def extract_single_entry_or_inline(text: str):
    # same logic; reused for clarity
    return extract_inline_entries(text)


def _clean_name(raw: str) -> str:
    s = re.sub(r"^[\s\-+]+|[\s\-+:：]+$", "", raw)
    return s.strip()


def _valid_name(name: str) -> bool:
    if not name:
        return False
    plain = re.sub(r"[*_`]", "", name).strip()
    if not plain:
        return False
    if plain.startswith(("//", ")", "）", "/")):
        return False
    if "://" in plain:
        return False
    if re.fullmatch(r"[（(].*[）)]", plain):
        return False
    return True


def _trailing_notes(text: str, pos: int) -> str | None:
    rest = text[pos:].lstrip()
    if rest.startswith(("（", "(")):
        opener = rest[0]
        closer = "）" if opener == "（" else ")"
        depth = 0
        for i, ch in enumerate(rest):
            if ch == opener:
                depth += 1
            elif ch == closer:
                depth -= 1
                if depth == 0:
                    return rest[1:i]
    return None


# ---------------------------------------------------------------------------
# migration drivers

LAYER_LIKE = {"layer", "subbranch"}
PROSE_TYPES = {"doc_top", "main_overview", "branch_intro", "branch",
               "crosscut", "other"}


def migrate(conn: sqlite3.Connection):
    ensure_columns(conn)
    conn.execute("DELETE FROM prose_blocks")

    section_rows = conn.execute(
        "SELECT key, section_type, body FROM sections ORDER BY position"
    ).fetchall()

    layer_n = entry_n = prose_n = 0
    for key, stype, body in section_rows:
        body = body or ""
        if stype in PROSE_TYPES:
            conn.execute(
                "INSERT INTO prose_blocks(section_key, kind, body) VALUES(?, ?, ?)",
                (key, "full", body),
            )
            prose_n += 1
        elif stype == "summary_table":
            # split intro prose (before first `|` line) and outro (after)
            lines = body.split("\n")
            first_tbl = next((i for i, ln in enumerate(lines)
                              if ln.startswith("|")), len(lines))
            intro = "\n".join(lines[:first_tbl]).rstrip()
            # outro: lines after last `|` line
            last_tbl = max((i for i, ln in enumerate(lines)
                            if ln.startswith("|")), default=-1)
            outro = "\n".join(lines[last_tbl + 1:]).strip() \
                if last_tbl >= 0 else ""
            block = intro
            if outro:
                block += "\n\n---OUTRO---\n" + outro
            conn.execute(
                "INSERT INTO prose_blocks(section_key, kind, body) VALUES(?, ?, ?)",
                (key, "summary_intro", block),
            )
            prose_n += 1
        elif stype == "refs":
            # nothing to migrate; rendered from refs table
            pass
        elif stype in LAYER_LIKE:
            intro, groups = parse_section(body)
            if intro:
                conn.execute(
                    "INSERT INTO prose_blocks(section_key, kind, body) VALUES(?, ?, ?)",
                    (key, "intro", intro),
                )
            n = apply_groups_to_entries(conn, key, groups)
            layer_n += 1
            entry_n += n
        else:
            print(f"  ! unhandled section_type={stype} key={key}")

    print(f"migrated {layer_n} layer/sub sections, "
          f"{entry_n} entries tagged with group/layout, "
          f"{prose_n} prose blocks captured.")


def apply_groups_to_entries(conn, section_key: str, groups: list[dict]) -> int:
    """Update entries rows in this section with group_*, bullet_* columns.
       Match entries by (ref_num, url, name) within the section."""
    # build entry rows for this section, keyed by (ref_num, url, name)
    existing = conn.execute(
        "SELECT id, name, url, position FROM entries WHERE section_key=? "
        "ORDER BY position", (section_key,)
    ).fetchall()
    by_key: dict[tuple, list[int]] = {}
    for eid, name, url, pos in existing:
        ref = conn.execute(
            "SELECT ref_num FROM entry_refs WHERE entry_id=? "
            "ORDER BY position LIMIT 1", (eid,)
        ).fetchone()
        rn = ref[0] if ref else None
        by_key.setdefault((rn, url, name), []).append(eid)

    used: set[int] = set()
    n = 0
    for gpos, grp in enumerate(groups):
        for ent in grp["entries"]:
            key = (ent["ref_num"], ent["url"], ent["name"])
            candidates = by_key.get(key) or []
            target = next((c for c in candidates if c not in used), None)
            if target is None:
                continue
            used.add(target)
            conn.execute(
                "UPDATE entries SET group_position=?, group_label_display=?, "
                "group_layout=?, group_separator=?, bullet_position=?, "
                "bullet_sub_label=? WHERE id=?",
                (gpos, grp["label_display"], grp["layout"],
                 grp["separator"], ent.get("bullet_position"),
                 ent.get("sub_label"), target),
            )
            n += 1
    return n


# ---------------------------------------------------------------------------
# emit starter Jinja2 templates

def emit_templates(conn: sqlite3.Connection):
    TEMPLATES_DIR.mkdir(parents=True, exist_ok=True)

    # collect prose by section
    prose = {row[0]: row[2] for row in conn.execute(
        "SELECT section_key, kind, body FROM prose_blocks").fetchall()}

    # ---- _macros.j2 ----
    (TEMPLATES_DIR / "_macros.j2").write_text(
        textwrap.dedent('''\
        {#- Shared rendering macros. Data layout:
             entry = (name, url, notes, ref_num, group_position, group_label_display,
                      group_layout, group_separator, bullet_position, bullet_sub_label)
             ref   = (num, citation, url)
             cell  = (layer_code, branch_code, text)
             layer = (code, name)
             branch = (code, parent_code, name) -#}

        {%- macro render_entry(e) -%}
        {{- e.name }}[[{{ e.ref_num }}]]({{ e.url }})
        {%- if e.notes %}（{{ e.notes }}）{% endif -%}
        {%- endmacro -%}

        {%- macro render_entries_for(owner_code, entries) -%}
        {%- set section_entries = entries | selectattr('section_key', 'equalto', owner_code) | list -%}
        {%- set groups = section_entries | groupby('group_position') -%}
        {%- for gpos, gentries in groups -%}
        {%- set first = gentries[0] -%}
        {%- set layout = first.group_layout or 'bullets' -%}
        {%- set label = first.group_label_display -%}
        {%- if layout == 'inline' -%}
        {% if label %}**{{ label }}**：{% endif -%}
        {%- for e in gentries -%}{{ render_entry(e) }}{% if not loop.last %}{{ first.group_separator or '、' }}{% endif %}{%- endfor %}
        {% elif layout == 'bullets' -%}
        {% if label %}**{{ label }}**：
        {% endif -%}
        {%- set bullets = gentries | groupby('bullet_position') -%}
        {%- for bpos, bentries in bullets -%}
        {%- set b0 = bentries[0] -%}
        - {% if b0.bullet_sub_label %}**{{ b0.bullet_sub_label }}**：{% endif -%}
        {%- for e in bentries -%}{{ render_entry(e) }}{% if not loop.last %} + {% endif %}{%- endfor %}
        {% endfor -%}
        {%- endif -%}
        {%- if not loop.last %}

        {% endif -%}
        {%- endfor -%}
        {%- endmacro -%}

        {%- macro render_summary_table(layers, branches, cells) -%}
        | L | {% for b in branches %}{{ b.code }}. {{ b.name }}{% if not loop.last %} | {% endif %}{% endfor %} |
        |---|{% for b in branches %}---|{% endfor %}
        {% for lyr in layers -%}
        | {{ lyr.code }} {{ lyr.name }} | {% for b in branches -%}
        {{ cells.get((lyr.code, b.code), '') }}{% if not loop.last %} | {% endif %}
        {%- endfor %} |
        {% endfor -%}
        {%- endmacro -%}

        {%- macro render_refs(refs) -%}
        {% for r in refs -%}
        [{{ r.num }}] {{ r.citation }}{% if r.url %} [Online]. Available: <{{ r.url }}>{% endif %}

        {% endfor -%}
        {%- endmacro -%}
        '''),
        encoding="utf-8",
    )

    # ---- prose partials, one per section ----
    prose_dir = TEMPLATES_DIR / "prose"
    prose_dir.mkdir(exist_ok=True)
    for key, body in prose.items():
        (prose_dir / f"{key}.md").write_text(body + ("\n" if body and not body.endswith("\n") else ""),
                                              encoding="utf-8")

    # ---- main spine ----
    (TEMPLATES_DIR / "readme.md.j2").write_text(
