        {{ section_body.get(sub.code, '') | trim }}
        {%- endfor %}
        {%- endfor %}

        ## 几条横切的观察

        {{ prose.get('crosscut', '') | trim }}

        ## 参考文献

        {{ render_refs(refs) }}
        '''), encoding="utf-8")

    print(f"wrote templates to {TEMPLATES_DIR}/")


def main():
    if not DB_PATH.exists():
        sys.exit(f"db not found: {DB_PATH}")
    conn = sqlite3.connect(DB_PATH)
    migrate(conn)
    emit_templates()
    conn.close()


