        {%- if '---OUTRO---' in st %}
        {%- set st_intro, st_outro = st.split('---OUTRO---', 1) %}
        {%- else %}
        {%- set st_intro, st_outro = st, '' %}
        {%- endif %}

        {{ st_intro | trim }}

        {{ render_summary_table(layers, branches, cells) }}
        {%- if st_outro.strip() %}

        {{ st_outro | trim }}
        {%- endif %}

        ## A. LLM / Agent — 全栈总览（34 层）

        {{ prose.get('main-overview', '') | trim }}
        {%- for lyr in layers %}

        ## {{ lyr.code }} {{ lyr.name }}

        {% if lyr.code in prose %}{{ prose[lyr.code] | trim }}

        {% endif -%}
        {{ section_body.get(lyr.code, '') | trim }}
        {%- endfor %}

        ## 各领域分支细节（B–J，共享 L01–L09，从 L10 起分叉）

        {{ prose.get('parallel-intro', '') | trim }}
        {%- for br in branches if br.code != 'A' %}
        {%- if br.code in prose %}

        ### {{ br.code }} {{ br.name }}

        {{ prose[br.code] | trim }}
        {%- endif %}
        {%- for sub in sub_branches if sub.parent_code == br.code %}

        ### {{ sub.code }} {{ sub.name }}

        {% if sub.code in prose %}{{ prose[sub.code] | trim }}

        {% endif -%}
        {{ section_body.get(sub.code, '') | trim }}
        {%- endfor %}
        {%- endfor %}

        ## 几条横切的观察

        {{ prose.get('crosscut', '') | trim }}

        ## 参考文献

        {{ render_refs(refs) }}
        '''), encoding="utf-8")

    print(f"wrote templates to {TEMPLATES_DIR}/")


def main():
    if not DB_PATH.exists():
        sys.exit(f"db not found: {DB_PATH}")
    conn = sqlite3.connect(DB_PATH)
    migrate(conn)
    emit_templates()
    conn.close()


